changeSet.sql:
SET LOCAL lock_timeout='30s';
ALTER TABLE feedback DROP CONSTRAINT ck_feedback_stop_reason;
ALTER TABLE feedback ADD CONSTRAINT ck_feedback_stop_reason CHECK (stop_reason IS NULL OR stop_reason IN ('VOLUME_CAPPED','COMPOSER_WITHHELD','NOTHING_NEW','REPEATS_DELIVERED_NOTE','REACTED_DISAGREE','REACTED_NOT_APPLICABLE','CONVERSATION_EXPIRED','DELIVERY_UNCONFIRMED','ITEM_GONE','ITEM_CLOSED','ITEM_MERGED','ITEM_STATE_INELIGIBLE','ISSUE_SNAPSHOT_CHANGED','PUBLIC_SUBJECT_INELIGIBLE','NO_AI','DELIVERY_OFF','PERSON_SUPPRESSED','RECIPIENT_UNAVAILABLE','EMPTY_AFTER_SANITIZE','INSTANCE_SILENCED','FEEDBACK_OFF','WORKSPACE_DISABLED','WORKSPACE_DELIVERY_PAUSED','STALE_ROLLOUT_REVISION','OUTSIDE_CURRENT_SCOPE','APPROVAL_STALE','APPROVAL_NO_LONGER_ELIGIBLE','PRACTICE_REQUIRES_APPROVAL','BACKFILL_QUIET','RESULT_MARKED_INCORRECT','REVIEWED_VERSION_CHANGED','REVIEW_CANCELLED','EVIDENCE_NOT_PERMITTED','NO_EVIDENCE','UNCORROBORATED','PUBLIC_HISTORY_CHANGED','PUBLIC_DELIVERY_UNRESOLVED'));
ALTER TABLE feedback_copy DROP CONSTRAINT ck_feedback_copy_stop_reason;
ALTER TABLE feedback_copy ADD CONSTRAINT ck_feedback_copy_stop_reason CHECK (stop_reason IS NULL OR stop_reason IN ('VOLUME_CAPPED','COMPOSER_WITHHELD','NOTHING_NEW','REPEATS_DELIVERED_NOTE','REACTED_DISAGREE','REACTED_NOT_APPLICABLE','CONVERSATION_EXPIRED','DELIVERY_UNCONFIRMED','ITEM_GONE','ITEM_CLOSED','ITEM_MERGED','ITEM_STATE_INELIGIBLE','ISSUE_SNAPSHOT_CHANGED','PUBLIC_SUBJECT_INELIGIBLE','NO_AI','DELIVERY_OFF','PERSON_SUPPRESSED','RECIPIENT_UNAVAILABLE','EMPTY_AFTER_SANITIZE','INSTANCE_SILENCED','FEEDBACK_OFF','WORKSPACE_DISABLED','WORKSPACE_DELIVERY_PAUSED','STALE_ROLLOUT_REVISION','OUTSIDE_CURRENT_SCOPE','APPROVAL_STALE','APPROVAL_NO_LONGER_ELIGIBLE','PRACTICE_REQUIRES_APPROVAL','BACKFILL_QUIET','RESULT_MARKED_INCORRECT','REVIEWED_VERSION_CHANGED','REVIEW_CANCELLED','EVIDENCE_NOT_PERMITTED','NO_EVIDENCE','UNCORROBORATED','PUBLIC_HISTORY_CHANGED','PUBLIC_DELIVERY_UNRESOLVED'));
ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_entity_type;
ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type CHECK (entity_type IN (
  'PRACTICE_REVIEW_SETTINGS','AGENT_BINDING','AGENT_CONFIG','AI_CONFIG_BINDING','WORKSPACE_ROLE',
  'ACTIVITY_AUTOMATION','WORKSPACE_FEATURES','WORKSPACE_STATUS','WORKSPACE_TOKEN','WORKSPACE_VISIBILITY',
  'PRACTICE_ACTIVE','PRACTICE_USAGE','PRACTICE_DEFINITION','PRACTICE_GROUP','CATALOG_PRACTICE','CATALOG_GROUP',
  'WORKSPACE_INSTANCE_LLM_BUDGET','WORKSPACE_OWN_PROVIDER_LLM_BUDGET','WORKSPACE_LLM_BUDGET',
  'WORKSPACE_BYO_LLM_BUDGET','REVIEW_BATCH','REVIEW_SCHEDULE','WORKSPACE_LLM_CONNECTION','WORKSPACE_LLM_MODEL'
 ,'FEEDBACK_DELIVERY_RECHECK'));

rollback.sql:
DO $restore$
BEGIN
 IF EXISTS (SELECT 1 FROM feedback WHERE stop_reason IN ('PUBLIC_HISTORY_CHANGED','PUBLIC_DELIVERY_UNRESOLVED')) THEN RAISE EXCEPTION 'Cannot remove publication vocabulary while feedback rows use it; use a forward fix or restore the matching backup.'; END IF;
 IF EXISTS (SELECT 1 FROM feedback_copy WHERE stop_reason IN ('PUBLIC_HISTORY_CHANGED','PUBLIC_DELIVERY_UNRESOLVED')) THEN RAISE EXCEPTION 'Cannot remove publication vocabulary while feedback_copy rows use it; use a forward fix or restore the matching backup.'; END IF;
 IF EXISTS (SELECT 1 FROM config_audit_event WHERE entity_type IN ('FEEDBACK_DELIVERY_RECHECK')) THEN RAISE EXCEPTION 'Cannot remove publication vocabulary while config_audit_event rows use it; use a forward fix or restore the matching backup.'; END IF;
