 ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type CHECK (entity_type IN (
  'PRACTICE_REVIEW_SETTINGS','AGENT_BINDING','AGENT_CONFIG','AI_CONFIG_BINDING','WORKSPACE_ROLE',
  'ACTIVITY_AUTOMATION','WORKSPACE_FEATURES','WORKSPACE_STATUS','WORKSPACE_TOKEN','WORKSPACE_VISIBILITY',
  'PRACTICE_ACTIVE','PRACTICE_USAGE','PRACTICE_DEFINITION','PRACTICE_GROUP','CATALOG_PRACTICE','CATALOG_GROUP',
  'WORKSPACE_INSTANCE_LLM_BUDGET','WORKSPACE_OWN_PROVIDER_LLM_BUDGET','WORKSPACE_LLM_BUDGET',
  'WORKSPACE_BYO_LLM_BUDGET','REVIEW_BATCH','REVIEW_SCHEDULE','WORKSPACE_LLM_CONNECTION','WORKSPACE_LLM_MODEL'
